-- =====================================================
-- R__seed_exercises: 운동 종목 시드 (반복 마이그레이션)
--
-- 자동 생성 파일 — 직접 수정하지 말 것.
--   원본 : backend/src/main/resources/data/exercises.csv (274종목)
--   생성 : python scripts/gen_exercise_seed.py
--
-- 자연키 name_ko 기준 UPSERT. CSV를 고치고 재생성하면 체크섬이 바뀌어
-- Flyway가 자동으로 재실행한다.
-- 사용자가 만든 종목(owner_id 있음)은 이름이 사람마다 따로라, 기본 종목끼리의
-- 부분 유일 인덱스(uq_exercises_builtin_name, V16)로만 겹침을 본다.
-- delt_region 배분 근거: 「설계 변경 로그」 LOG-09
-- =====================================================

ON CONFLICT (name_ko) WHERE owner_id IS NULL DO UPDATE SET
    name_en        = EXCLUDED.name_en,
    body_part      = EXCLUDED.body_part,
    primary_muscle = EXCLUDED.primary_muscle,
    push_pull      = EXCLUDED.push_pull,
    measure_type   = EXCLUDED.measure_type,
    equipment      = EXCLUDED.equipment,
    delt_region    = EXCLUDED.delt_region,
    group_name     = EXCLUDED.group_name,
    starter_rank   = EXCLUDED.starter_rank,
    common_rank    = EXCLUDED.common_rank;
